<?php
namespace App\Http\Controllers;
use App\Models\EventBudget; use App\Models\PromotionEvent; use Illuminate\Http\JsonResponse; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\View\View;
  class EventBudgetController extends Controller { public function index(Request $request):View{$filters=$request->validate(['event'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date'],'search'=>['nullable','string','max:255']]);$budgets=EventBudget::query()->join('promotion_events as event','event_budgets.promotion_event_id','=','event.id')->select('event_budgets.*','event.title as event_title','event.start_date as event_date')->when($filters['event']??null,fn($q,$id)=>$q->where('promotion_event_id',$id))->when($filters['from']??null,fn($q,$date)=>$q->whereDate('event.start_date','>=',$date))->when($filters['to']??null,fn($q,$date)=>$q->whereDate('event.start_date','<=',$date))->when($filters['search']??null,fn($q,$term)=>$q->where('event.title','like',"%{$term}%"))->latest('event_budgets.created_at')->get();return view('event-budgets.index',['budgets'=>$budgets,'filters'=>$filters,'events'=>$this->events()]);} public function create():View{return view('event-budgets.create',['budget'=>new EventBudget(),'events'=>$this->events()]);} public function edit(EventBudget $budget):View{return view('event-budgets.create',['budget'=>$budget->load('items'),'events'=>$this->events()]);} public function event(PromotionEvent $event):JsonResponse{return response()->json(['date'=>$event->start_date?->format('Y-m-d'),'title'=>$event->title]);} public function store(Request $request):RedirectResponse{$this->saveBudget(new EventBudget(),$this->validated($request));return redirect()->route('budgets.index')->with('success','Budget saved successfully.');} public function update(Request $request,EventBudget $budget):RedirectResponse{$this->saveBudget($budget,$this->validated($request));return redirect()->route('budgets.index')->with('success','Budget updated successfully.');} public function destroy(EventBudget $budget):RedirectResponse{$budget->items()->delete();$budget->delete();return back()->with('success','Budget deleted successfully.');} private function events(){return PromotionEvent::orderByDesc('start_date')->get(['id','title','start_date']);} private function validated(Request $request):array{return $request->validate(['promotion_event_id'=>['required','exists:promotion_events,id'],'remarks'=>['nullable','string','max:5000'],'items'=>['required','array','min:1'],'items.*.title'=>['required','string','max:255'],'items.*.quantity'=>['required','numeric','min:0'],'items.*.unit_price'=>['required','numeric','min:0'],'items.*.note'=>['nullable','string','max:255']]);} private function saveBudget(EventBudget $budget,array $data):void{DB::transaction(function()use($budget,$data){$total=collect($data['items'])->sum(fn($item)=>(float)$item['quantity']*(float)$item['unit_price']);$budget->fill(['promotion_event_id'=>$data['promotion_event_id'],'remarks'=>$data['remarks']??null,'total_amount'=>$total])->save();$budget->items()->delete();foreach($data['items'] as $item)$budget->items()->create($item+['amount'=>$item['quantity']*$item['unit_price']]);});} }
